# Builds en/index.html from index.html: same markup, English copy,
# asset paths one level up. Run after editing the Greek page:
#   python3 scripts/make-en.py
import re, pathlib, sys

root = pathlib.Path(__file__).resolve().parent.parent
h = (root / "index.html").read_text(encoding="utf-8")

def sub(old, new, count=1):
    global h
    n = h.count(old)
    if n < count:
        sys.exit(f"make-en: expected {count}x, found {n}x: {old[:70]!r}")
    h = h.replace(old, new)

# paths
h = re.sub(r'(src|href|srcset|poster)="assets/', r'\1="../assets/', h)
h = re.sub(r'(, )assets/', r'\1../assets/', h)
h = h.replace("url(assets/", "url(../assets/")

